class Solution:
    def minimumDifference(self, nums: List[int]) -> int:
        n = len(nums)
        best = -1
        for i in range(n - 1):
            if any(nums[j] >= nums[j + 1] for j in range(i)):
                continue
            if any(nums[j] <= nums[j + 1] for j in range(i + 1, n - 1)):
                continue
            d = abs(sum(nums[:i + 1]) - sum(nums[i + 1:]))
            if best == -1 or d < best:
                best = d
        return best

