class Solution {
public:
    int minimumDifference(vector<int>& nums) {
        int n = nums.size(), best = -1;
        for (int i = 0; i + 1 < n; i++) {
            bool ok = true;
            for (int j = 0; j < i; j++) if (nums[j] >= nums[j+1]) ok = false;
            for (int j = i + 1; j + 1 < n; j++) if (nums[j] <= nums[j+1]) ok = false;
            if (!ok) continue;
            long long l = accumulate(nums.begin(), nums.begin()+i+1, 0LL);
            long long r = accumulate(nums.begin()+i+1, nums.end(), 0LL);
            long long d = llabs(l - r);
            if (best == -1 || d < best) best = (int)d;
        }
        return best;
    }
};

