class Solution {
    public int minimumDifference(int[] nums) {
        int n = nums.length;
        boolean[] inc = new boolean[n], dec = new boolean[n];
        Arrays.fill(inc, true); Arrays.fill(dec, true);
        for (int i = 1; i < n; i++) inc[i] = inc[i-1] && nums[i] > nums[i-1];
        for (int i = n - 2; i >= 0; i--) dec[i] = dec[i+1] && nums[i] > nums[i+1];
        long total = 0, pre = 0;
        for (int x : nums) total += x;
        int ans = -1;
        for (int i = 0; i + 1 < n; i++) {
            pre += nums[i];
            if (inc[i] && dec[i+1]) {
                long d = Math.abs(pre - (total - pre));
                if (ans == -1 || d < ans) ans = (int) d;
            }
        }
        return ans;
    }
}

